      taxiya: { a: "<b>TaxiYa</b> é uma plataforma para empresas de táxi operarem <b>sem ligações nem planos de dados caros</b>: app de passageiro, app de motorista e painel da central, com despacho em tempo real.", url: URL.taxiya, cta: "Ver TaxiYa →" },
