      materiales: "हम <b>FDM</b> 3D प्रिंटिंग (PLA, PETG, ABS, लचीला TPU) और बारीक पुर्ज़ों के लिए <b>रेज़िन</b> करते हैं; MDF, ऐक्रेलिक, गत्ते और चमड़े पर <b>लेज़र</b> कटिंग व एनग्रेविंग; और जब मज़बूती या बेहतर फ़िनिश चाहिए तो <b>CNC</b>। सही सामग्री इस्तेमाल पर निर्भर करती है — बताइए पुर्ज़ा किस काम का है, मैं सलाह देता हूँ।",
      tecnologias: "सॉफ़्टवेयर में: <b>JavaScript, Next.js, Python, Firebase और Supabase</b>। इलेक्ट्रॉनिक्स में: <b>Arduino, ESP32 और Raspberry Pi</b>। निर्माण में: <b>FDM और रेज़िन 3D प्रिंटिंग, लेज़र और CNC</b>, साथ में <b>2D/3D CAD</b> डिज़ाइन। और <b>AI</b> वहीं इस्तेमाल करते हैं जहाँ वह सचमुच काम आती है।",
      donde: "हम <b>मेडेयीन, कोलंबिया</b> 🇨🇴 में हैं, पर ग्राहक कहीं के भी हो सकते हैं: सॉफ़्टवेयर क्लाउड में दिया जाता है और भौतिक पुर्ज़े कूरियर से भेजे जाते हैं।",
      envios: "हाँ: <b>सॉफ़्टवेयर</b> क्लाउड में दिया जाता है, इसलिए आप दुनिया में कहीं भी हों फ़र्क नहीं पड़ता। <b>भौतिक पुर्ज़े</b> पूरे <b>कोलंबिया</b> में कूरियर से जाते हैं; देश के बाहर हों तो Henry को गंतव्य बताइए, वे पहले ही बता देंगे कि भेजना फ़ायदेमंद है या नहीं।",
      horario: "ग्राहक खाता होने पर आप <b>किसी भी समय</b> लिख सकते हैं — Henry आमतौर पर 24 घंटे के भीतर जवाब देते हैं, सोमवार से शनिवार। यह चैट तो 24/7 उपलब्ध है। 😉",
      portafolio: 'ज़रूर। <a href="#proyectos">प्रोजेक्ट</a> वाले हिस्से में असली काम देख सकते हैं: <b>EvaIA</b>, <b>TaxiYa</b>, <b>IncubApp</b>, <b>A Tiempo Logística</b> और <b>PrivacyCheck</b>, कई के लाइव डेमो भी हैं। क्या इनमें से कोई आपकी ज़रूरत जैसा लगता है?',
      privacycheck: { a: "<b>PrivacyCheck</b> कोलंबिया के <b>क़ानून 1581</b> (व्यक्तिगत डेटा सुरक्षा) के अनुपालन का स्व-मूल्यांकन मंच है: कंपनी दर्ज कीजिए, प्रश्नावली भरिए और <b>स्कोर, कमियाँ और AI से बनी कार्य-योजना</b> पाइए।", url: URL.privacycheck, cta: "PrivacyCheck खोलें →" },
      evaia: "<b>EvaIA</b> एक AI सहायक है जो <b>100% स्थानीय रूप से</b> आपके अपने कंप्यूटर पर चलता है: आवाज़ समझता है, बोलकर जवाब देता है, कैमरे से देखता है, डेटाबेस में याद रखता है और उसका अपना एनिमेटेड अवतार है। ख़ास बात यही है — <b>कोई बातचीत आपके कंप्यूटर से बाहर नहीं जाती</b>।",
      taxiya: { a: "<b>TaxiYa</b> टैक्सी कंपनियों को <b>बिना फ़ोन कॉल और महँगे डेटा प्लान</b> के चलाने का मंच है: यात्री ऐप, चालक ऐप और नियंत्रण कक्ष, रीयल-टाइम डिस्पैच के साथ।", url: URL.taxiya, cta: "TaxiYa देखें →" },
      incubapp: { a: "<b>IncubApp</b> हैचरी और फ़ार्म के लिए <b>बहु-कंपनी</b> SaaS है: फ़ोटो सहित राउंड, कार्य आदेश, बिक्री, लॉजिस्टिक्स, स्वास्थ्य और रीयल-टाइम प्रबंधन डैशबोर्ड, AI के साथ।", url: URL.incubapp, cta: "IncubApp देखें →" },
      atiempo: { a: "<b>A Tiempo Logística</b> ई-कॉमर्स के लिए <b>लास्ट-माइल लॉजिस्टिक्स</b> का SaaS मंच है: शिपमेंट ट्रैकिंग, गोदाम प्रबंधन, रूट बनाना और डिलीवरी पर भुगतान। Next.js और Supabase पर बना।", url: URL.atiempo, cta: "A Tiempo Logística देखें →" },
      cuenta: "कारण बताता हूँ, यह वाजिब है: हम वेबसाइट पर <b>न नंबर छापते हैं न ईमेल</b>। इससे बॉट का स्पैम बचता है और हमें पता रहता है कि बात किससे हो रही है। खाता बनाते ही (मुफ़्त, एक मिनट से कम) WhatsApp और ईमेल पर <b>Henry से सीधा संपर्क</b> खुल जाता है।",
      privacidad: "आपका डेटा <b>सिर्फ़</b> इसलिए है कि Henry आपसे संपर्क करें और प्रोजेक्ट पर नज़र रखें: <b>हम उसे न बेचते हैं, न साझा करते हैं, और न आपका इनबॉक्स भरते हैं</b>। पासवर्ड एन्क्रिप्टेड रखे जाते हैं, और यह बातचीत <b>आपके ब्राउज़र से बाहर नहीं जाती</b>।",
      contacto: "अगर आपका ग्राहक खाता पहले से है, तो यह रहा WhatsApp का सीधा रास्ता। Henry आमतौर पर 24 घंटे में जवाब देते हैं।",
      contact_guest: "Henry से बात करने या कोटेशन माँगने के लिए पहले <b>अपना ग्राहक खाता बनाइए</b> — मुफ़्त है और एक मिनट से कम लगता है। इससे हमारा संपर्क स्पैम से बचा रहता है।",
      humano: "बिल्कुल! इंसान से बात करने जैसा कुछ नहीं। <b>Henry</b> ख़ुद आपकी मदद करेंगे:",
