      ask_more: ["थोड़ा और बताइए ताकि मैं सही सलाह दे सकूँ: यह किस काम के लिए है और कब तक चाहिए?"],
      fallback: ["यह मुझे ठीक-ठीक नहीं पता, और मैं मनगढ़ंत जवाब नहीं देना चाहता। बेहतर होगा कि यह सीधे Henry से पूछें — या थोड़ा और बताइए, मैं सही सेवा की ओर इशारा कर देता हूँ:"],
      aliados: { a: "हम अपने साझेदार <b>Galactic AIMA</b> के साथ मिलकर काम करते हैं। जब किसी प्रोजेक्ट में ऐसी विशेषज्ञता चाहिए जो हमारे पास नहीं है, तो हम तुक्का लगाने के बजाय किसी अच्छे व्यक्ति को जोड़ना पसंद करते हैं।", url: URL.aliado, cta: "Galactic AIMA →" },
